CREATE TABLE partners(id BINARY(16) PRIMARY KEY,tenant_id BINARY(16) NOT NULL,company_name VARCHAR(160) NOT NULL,contact_name VARCHAR(120) NOT NULL,email VARCHAR(190),phone VARCHAR(32),commission_percent DECIMAL(5,2) NOT NULL,status VARCHAR(20) NOT NULL,created_at TIMESTAMP(6) NOT NULL,updated_at TIMESTAMP(6) NOT NULL,INDEX idx_partner_tenant(tenant_id));
CREATE TABLE technicians(id BINARY(16) PRIMARY KEY,tenant_id BINARY(16) NOT NULL,name VARCHAR(120) NOT NULL,email VARCHAR(190) NOT NULL,phone VARCHAR(32),skills VARCHAR(500),status VARCHAR(20) NOT NULL,created_at TIMESTAMP(6) NOT NULL,updated_at TIMESTAMP(6) NOT NULL,INDEX idx_tech_tenant(tenant_id));
CREATE TABLE rfid_cards(id BINARY(16) PRIMARY KEY,tenant_id BINARY(16) NOT NULL,card_uid VARCHAR(64) NOT NULL UNIQUE,label VARCHAR(120),user_id BINARY(16),notes VARCHAR(500),status VARCHAR(20) NOT NULL,issued_at TIMESTAMP(6) NOT NULL,revoked_at TIMESTAMP(6),INDEX idx_rfid_tenant(tenant_id),INDEX idx_rfid_user(user_id));
